const event = $json;
const desc = (event.description || '') + ' ' + (event.location || '') + ' ' + (event.hangoutLink || '');
const urlMatch = desc.match(/https?:\/\/(?:[a-zA-Z0-9-]+\.)?(?:zoom\.us|meet\.google\.com|teams\.microsoft\.com|teams\.live\.com)\/[^\s"'<>]+/);
if (!urlMatch) {
  return [];
}
return [{
  json: {
    meeting_url: urlMatch[0],
    join_at: event.start && event.start.dateTime,
    customer_name: (event.summary || '').split(/[\s_\-]+/)[0] || 'unknown',
    meeting_purpose: event.summary || 'meeting'
  }
}];

