parameters.functionCode:
const utterances = $json.utterances || [];
const transcriptText = utterances.map(u => `${u.speaker || 'speaker'}: ${u.text || (u.words || []).map(w => w.text).join(' ')}`).join('\n');
return [{
  json: {
    transcript_text: transcriptText,
    speakers: [...new Set(utterances.map(u => u.speaker || 'speaker'))],
    customer_name: $json.metadata && $json.metadata.customer_name,
    meeting_purpose: $json.metadata && $json.metadata.meeting_purpose
  }
}];

