const date = new Date();
const ymd = `${date.getFullYear()}${String(date.getMonth()+1).padStart(2,'0')}${String(date.getDate()).padStart(2,'0')}`;
const sanitize = s => (s || 'unknown').replace(/[^A-Za-z0-9一-龯ぁ-んァ-ヶー]+/g, '_');
return [{
  json: {
    record_key: `${ymd}_${sanitize($node['Step3 - Build Context'].json.customer_name)}_${sanitize($node['Step3 - Build Context'].json.meeting_purpose)}`,
